#include "recording/wayland/WaylandStream.h"

#include "capture/wayland/WaylandConnection.h"
#include "capture/wayland/WaylandFreeze.h"

#include <QPainter>
#include <QScreen>
// Qt's native interface for Wayland screens: their wl_output.
#include <QtGui/qscreen_platform.h>

#include <wayland-client.h>
// Generated by wayland-scanner from protocols/ (CMakeLists.txt).
#include "hyprland-toplevel-export-v1-client-protocol.h"
#include "wlr-screencopy-unstable-v1-client-protocol.h"

#include <sys/mman.h>
#include <unistd.h>

#include <functional>

namespace {

constexpr uint32_t kScreencopyVersion = 3;
constexpr uint32_t kToplevelExportVersion = 1;
// How often the answers are read while a frame is on its way.
constexpr int kPollMs = 4;
// So many frames in a row without a picture end the stream (half a second).
constexpr int kMaxFailures = 15;
// overlay_cursor: the compositor draws the pointer into the copy (F-50).
constexpr int32_t kWithPointer = 1;

wl_output *outputOf(QScreen *screen)
{
    auto *native = screen ? screen->nativeInterface<QNativeInterface::QWaylandScreen>() : nullptr;
    return native ? native->output() : nullptr;
}

} // namespace

// One monitor or the window: the copy request of the current frame, and
// the shared memory it is copied into, kept for the next frames.
struct StreamSource
{
    wl_shm *shm = nullptr;
    wl_output *output = nullptr;  // a monitor, or
    uint32_t handle = 0;          // a window
    QRect native;                 // monitors: where it goes in the picture
    std::function<void()> onDone; // tells the stream

    zwlr_screencopy_frame_v1 *screenFrame = nullptr;
    hyprland_toplevel_export_frame_v1 *windowFrame = nullptr;
    bool announcesBuffers = true;

    // This frame's offer.
    bool offered = false;
    uint32_t format = 0;
    uint32_t width = 0;
    uint32_t height = 0;
    uint32_t stride = 0;
    bool yInvert = false;

    // The buffer, made for an earlier offer and kept while it still fits.
    wl_buffer *buffer = nullptr;
    uchar *data = nullptr;
    size_t size = 0;
    uint32_t bufferFormat = 0;
    uint32_t bufferWidth = 0;
    uint32_t bufferHeight = 0;
    uint32_t bufferStride = 0;

    bool done = true;
    QImage image;

    ~StreamSource()
    {
        destroyFrame();
        destroyBuffer();
    }

    void destroyFrame()
    {
        if (screenFrame)
            zwlr_screencopy_frame_v1_destroy(screenFrame);
        if (windowFrame)
            hyprland_toplevel_export_frame_v1_destroy(windowFrame);
        screenFrame = nullptr;
        windowFrame = nullptr;
    }

    void destroyBuffer()
    {
        if (buffer)
            wl_buffer_destroy(buffer);
        if (data)
            munmap(data, size);
        buffer = nullptr;
        data = nullptr;
        size = 0;
    }

    // A new copy request; the answers come through the listeners below.
    void begin()
    {
        done = false;
        offered = false;
        yInvert = false;
        image = QImage();
    }

    void offer(uint32_t f, uint32_t w, uint32_t h, uint32_t s)
    {
        if (done || offered || WaylandFreeze::imageFormat(f) == QImage::Format_Invalid)
            return;
        offered = true;
        format = f;
        width = w;
        height = h;
        stride = s;
        if (!announcesBuffers)
            copy();
    }

    // All offers are in: copy into the buffer.
    void copy()
    {
        if (done)
            return;
        if (!offered || !ensureBuffer()) {
            finish(false);
            return;
        }
        if (screenFrame)
            zwlr_screencopy_frame_v1_copy(screenFrame, buffer);
        else if (windowFrame)
            hyprland_toplevel_export_frame_v1_copy(windowFrame, buffer, 1); // 1: now, not at the next damage
    }

    bool ensureBuffer()
    {
        if (buffer && bufferFormat == format && bufferWidth == width && bufferHeight == height
            && bufferStride == stride)
            return true;
        destroyBuffer();
        const size_t bytes = size_t(stride) * height;
        if (bytes == 0)
            return false;
        // Shared memory, as in WaylandFreeze: an anonymous file both sides map.
        const int fd = memfd_create("snapslash-video", MFD_CLOEXEC);
        if (fd < 0)
            return false;
        if (ftruncate(fd, off_t(bytes)) < 0) {
            close(fd);
            return false;
        }
        void *mapped = mmap(nullptr, bytes, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
        if (mapped == MAP_FAILED) {
            close(fd);
            return false;
        }
        data = static_cast<uchar *>(mapped);
        size = bytes;
        wl_shm_pool *pool = wl_shm_create_pool(shm, fd, int32_t(bytes));
        buffer = wl_shm_pool_create_buffer(pool, 0, int32_t(width), int32_t(height), int32_t(stride), format);
        wl_shm_pool_destroy(pool);
        close(fd);
        bufferFormat = format;
        bufferWidth = width;
        bufferHeight = height;
        bufferStride = stride;
        return buffer != nullptr;
    }

    void finish(bool ready)
    {
        if (done)
            return;
        // Without alpha: a window's transparent corners become black.
        if (ready)
            image = WaylandFreeze::toImage(data, int(width), int(height), int(stride), format, yInvert, false);
        done = true;
        destroyFrame();
        onDone();
    }
};

namespace {

// The C callbacks of both protocols, forwarding to the source in `data`.
StreamSource *sourceOf(void *data)
{
    return static_cast<StreamSource *>(data);
}

void screenBuffer(void *data, zwlr_screencopy_frame_v1 *, uint32_t format, uint32_t width, uint32_t height,
                  uint32_t stride)
{
    sourceOf(data)->offer(format, width, height, stride);
}
void screenFlags(void *data, zwlr_screencopy_frame_v1 *, uint32_t flags)
{
    sourceOf(data)->yInvert = flags & ZWLR_SCREENCOPY_FRAME_V1_FLAGS_Y_INVERT;
}
void screenReady(void *data, zwlr_screencopy_frame_v1 *, uint32_t, uint32_t, uint32_t)
{
    sourceOf(data)->finish(true);
}
void screenFailed(void *data, zwlr_screencopy_frame_v1 *)
{
    sourceOf(data)->finish(false);
}
void screenDamage(void *, zwlr_screencopy_frame_v1 *, uint32_t, uint32_t, uint32_t, uint32_t) {}
void screenDmabuf(void *, zwlr_screencopy_frame_v1 *, uint32_t, uint32_t, uint32_t) {}
void screenBufferDone(void *data, zwlr_screencopy_frame_v1 *)
{
    sourceOf(data)->copy();
}

const zwlr_screencopy_frame_v1_listener kScreenListener = {
    screenBuffer, screenFlags, screenReady, screenFailed, screenDamage, screenDmabuf, screenBufferDone,
};

void windowBuffer(void *data, hyprland_toplevel_export_frame_v1 *, uint32_t format, uint32_t width, uint32_t height,
                  uint32_t stride)
{
    sourceOf(data)->offer(format, width, height, stride);
}
void windowDamage(void *, hyprland_toplevel_export_frame_v1 *, uint32_t, uint32_t, uint32_t, uint32_t) {}
void windowFlags(void *data, hyprland_toplevel_export_frame_v1 *, uint32_t flags)
{
    sourceOf(data)->yInvert = flags & HYPRLAND_TOPLEVEL_EXPORT_FRAME_V1_FLAGS_Y_INVERT;
}
void windowReady(void *data, hyprland_toplevel_export_frame_v1 *, uint32_t, uint32_t, uint32_t)
{
    sourceOf(data)->finish(true);
}
void windowFailed(void *data, hyprland_toplevel_export_frame_v1 *)
{
    sourceOf(data)->finish(false);
}
void windowDmabuf(void *, hyprland_toplevel_export_frame_v1 *, uint32_t, uint32_t, uint32_t) {}
void windowBufferDone(void *data, hyprland_toplevel_export_frame_v1 *)
{
    sourceOf(data)->copy();
}

const hyprland_toplevel_export_frame_v1_listener kWindowListener = {
    windowBuffer, windowDamage, windowFlags, windowReady, windowFailed, windowDmabuf, windowBufferDone,
};

} // namespace

WaylandStream::WaylandStream(QObject *parent)
    : QObject(parent)
{
    m_poll.setInterval(kPollMs);
    connect(&m_poll, &QTimer::timeout, this, &WaylandStream::poll);
}

WaylandStream::~WaylandStream()
{
    stop();
}

bool WaylandStream::bindManagers(bool window)
{
    WaylandConnection *connection = WaylandConnection::instance();
    if (!connection)
        return false;
    m_shm = static_cast<wl_shm *>(connection->bind(&wl_shm_interface, 1));
    if (window)
        m_toplevelExport = static_cast<hyprland_toplevel_export_manager_v1 *>(
            connection->bind(&hyprland_toplevel_export_manager_v1_interface, kToplevelExportVersion));
    else
        m_screencopy = static_cast<zwlr_screencopy_manager_v1 *>(
            connection->bind(&zwlr_screencopy_manager_v1_interface, kScreencopyVersion, &m_screencopyVersion));
    if (m_shm && (window ? m_toplevelExport != nullptr : m_screencopy != nullptr))
        return true;
    release();
    return false;
}

bool WaylandStream::startScreens(const QList<QScreen *> &screens, const QList<QRect> &native)
{
    stop();
    if (screens.isEmpty() || screens.size() != native.size() || !bindManagers(false))
        return false;
    m_window = false;
    m_area = QRect();
    for (qsizetype i = 0; i < screens.size(); ++i) {
        auto source = std::make_unique<StreamSource>();
        source->shm = m_shm;
        source->output = outputOf(screens[i]);
        source->native = native[i];
        source->onDone = [this] { onSourceDone(); };
        if (!source->output) {
            release();
            return false;
        }
        m_area = m_area.united(native[i]);
        m_sources.push_back(std::move(source));
    }
    m_running = true;
    m_failures = 0;
    return true;
}

bool WaylandStream::startWindow(uint32_t handle, const QMargins &margins)
{
    stop();
    if (!bindManagers(true))
        return false;
    m_window = true;
    m_margins = margins;
    auto source = std::make_unique<StreamSource>();
    source->shm = m_shm;
    source->handle = handle;
    source->onDone = [this] { onSourceDone(); };
    m_sources.push_back(std::move(source));
    m_running = true;
    m_failures = 0;
    return true;
}

void WaylandStream::requestFrame()
{
    if (!m_running || m_waiting)
        return;
    m_waiting = true;
    for (const auto &source : m_sources) {
        source->begin();
        if (m_window) {
            source->windowFrame =
                hyprland_toplevel_export_manager_v1_capture_toplevel(m_toplevelExport, kWithPointer, source->handle);
            hyprland_toplevel_export_frame_v1_add_listener(source->windowFrame, &kWindowListener, source.get());
        } else {
            source->announcesBuffers = m_screencopyVersion >= 3;
            source->screenFrame = zwlr_screencopy_manager_v1_capture_output(m_screencopy, kWithPointer, source->output);
            zwlr_screencopy_frame_v1_add_listener(source->screenFrame, &kScreenListener, source.get());
        }
    }
    poll();
    if (m_waiting)
        m_poll.start();
}

void WaylandStream::poll()
{
    WaylandConnection *connection = WaylandConnection::instance();
    if (!connection || !connection->dispatchPending()) {
        stop();
        emit ended();
    }
}

void WaylandStream::onSourceDone()
{
    for (const auto &source : m_sources) {
        if (!source->done)
            return;
    }
    m_waiting = false;
    m_poll.stop();

    QImage frame;
    if (m_window) {
        const QImage &image = m_sources.front()->image;
        if (!image.isNull()) {
            const QRect inner = image.rect().marginsRemoved(m_margins);
            frame = inner.isValid() && inner != image.rect() ? image.copy(inner) : image;
        }
    } else {
        // The monitors side by side, as the overlay showed them; gaps black.
        bool complete = true;
        for (const auto &source : m_sources)
            complete = complete && !source->image.isNull();
        if (complete && m_sources.size() == 1) {
            frame = m_sources.front()->image;
        } else if (complete) {
            frame = QImage(m_area.size(), QImage::Format_RGB32);
            frame.fill(Qt::black);
            QPainter painter(&frame);
            for (const auto &source : m_sources)
                painter.drawImage(source->native.topLeft() - m_area.topLeft(), source->image);
        }
    }

    if (frame.isNull()) {
        // Not now: this runs inside a callback of the source, which stop()
        // would delete.
        if (++m_failures == kMaxFailures) {
            QTimer::singleShot(0, this, [this] {
                stop();
                emit ended();
            });
        }
        return;
    }
    m_failures = 0;
    emit frameReady(frame);
}

void WaylandStream::stop()
{
    if (!m_running && m_sources.empty() && !m_shm)
        return;
    m_running = false;
    m_waiting = false;
    m_poll.stop();
    release();
}

void WaylandStream::release()
{
    m_sources.clear();
    if (m_toplevelExport)
        hyprland_toplevel_export_manager_v1_destroy(m_toplevelExport);
    if (m_screencopy)
        zwlr_screencopy_manager_v1_destroy(m_screencopy);
    if (m_shm)
        wl_shm_destroy(m_shm);
    m_toplevelExport = nullptr;
    m_screencopy = nullptr;
    m_shm = nullptr;
    // Let the compositor see the destroy requests now.
    if (WaylandConnection *connection = WaylandConnection::instance())
        wl_display_flush(connection->display());
}
